# Available variables: # - env: environment on which the action is triggered # - model: model of the record on which the action is triggered; is a void recordset # - record: record on which the action is triggered; may be void # - records: recordset of all records on which the action is triggered in multi-mode; may be void # - time, datetime, dateutil, timezone: useful Python libraries # - float_compare: utility function to compare floats based on specific precision # - b64encode, b64decode: functions to encode/decode binary data # - log: log(message, level='info'): logging function to record debug information in ir.logging table # - _logger: _logger.info(message): logger to emit messages in server logs # - UserError: exception class for raising user-facing warning messages # - Command: x2many commands namespace # To return an action, assign: action = {...}
partner_to_subscribe = set() partner_tag = env.ref("rental.res_partner_category_rental_team", raise_if_not_found=False) if partner_tag: # and "website_id" in env.context: partners = env["res.partner"].search([("category_id", "=", partner_tag.id)]) partner_to_subscribe |= set(partners.ids)
if record.x_partner_email: partners = env["res.partner"].search([("email", "ilike", record.x_partner_email)]) if partners: partner = partners[0] else: customer_tag = env.ref("rental.res_partner_category_rental_customer", raise_if_not_found=False)
partner = env["res.partner"].create({ "name": record.x_partner_name, "email": record.x_partner_email, "phone": record.x_partner_phone, "category_id": [(4, customer_tag.id)] if customer_tag else [], }) partner_to_subscribe.add(partner.id) record.write({"x_partner_id": partner.id})
record.message_subscribe(partner_ids=list(partner_to_subscribe))
_logger.info(f"coucou ############################## {str(partners)}") _logger.info(f"ctx ############################## {str(env.context)}")
